import sys
root = sys.argv[1]
p = root + "/tests/browser/test_v52_ui_kit.py"
s = open(p).read()
s += '''

def test_v52_a_twin_keeps_its_tag_class_hosts_and_identity_whatever_the_painter_writes(room: HttpsCheckpoint) -> None:
    with sync_playwright() as driver:
        browser = driver.chromium.launch()
        page = _open(browser, room)
        result = page.evaluate("""() => {
          const nearHost = document.createElement('div'), farHost = document.createElement('div');
          document.body.append(nearHost, farHost);
          const twin = window.__aiTableUi.makeTwin({testid: 'real', tag: 'section', className: 'probe-class', paint: (el, side) => {
            el.dataset.testid = 'painted'; el.dataset.side = 'wrong'; el.dataset.twin = 'wrong';
            el.innerHTML = '<i data-testid="inner">' + side + '</i>'; }});
          twin.mount(nearHost, farHost);
          const info = (el) => ({tag: el.tagName, cls: el.className, testid: el.getAttribute('data-testid'), twin: el.getAttribute('data-twin'),
            side: el.getAttribute('data-side'), inner: el.querySelector('i').getAttribute('data-testid'), innerTwin: el.querySelector('i').getAttribute('data-twin'),
            innerSide: el.querySelector('i').getAttribute('data-side')});
          const out = {near: info(twin.near), far: info(twin.far), nearIn: twin.near.parentElement === nearHost, farIn: twin.far.parentElement === farHost};
          twin.setHidden(true); out.hidden = [twin.near.hidden, twin.far.hidden];
          twin.setHidden(false); out.shown = [twin.near.hidden, twin.far.hidden];
          twin.remove(); out.attached = [twin.near.isConnected, twin.far.isConnected];
          return out; }""")
        assert result["near"] == {"tag": "SECTION", "cls": "probe-class", "testid": "real", "twin": "wrong", "side": "near",
                                  "inner": "inner", "innerTwin": None, "innerSide": None}, result
        assert result["far"] == {"tag": "SECTION", "cls": "probe-class", "testid": None, "twin": "real", "side": "far",
                                 "inner": None, "innerTwin": "inner", "innerSide": "far"}, result
        assert result["nearIn"] is True and result["farIn"] is True
        assert result["hidden"] == [True, True] and result["shown"] == [False, False] and result["attached"] == [False, False]
        browser.close()
'''
open(p, "w").write(s)
PYEOF
